import{c as a,Q as i,j as r,m as o}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"OpenAI o3-mini System Card","description":"","frontmatter":{"url":"https://cdn.openai.com/o3-mini-system-card-feb10.pdf","title":"OpenAI o3-mini System Card","archived_date":"2026-06-24T00:00:00.000Z","authors":["OpenAI"],"domains":["system-card"],"pdf_path":"pdfs/openai-o3-mini-system-card.pdf","published_date":"2025-01-31T00:00:00.000Z","source_url":"https://cdn.openai.com/o3-mini-system-card-feb10.pdf"},"headers":[],"relativePath":"research/papers/2025-01-31-openai-o3-mini-system-card.md","filePath":"research/papers/2025-01-31-openai-o3-mini-system-card.md","lastUpdated":1785909234000}'),t={name:"research/papers/2025-01-31-openai-o3-mini-system-card.md"};function n(s,e,d,l,c,p){return i(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="openai-o3-mini-system-card" tabindex="-1">OpenAI o3-mini System Card <a class="header-anchor" href="#openai-o3-mini-system-card" aria-label="Permalink to &quot;OpenAI o3-mini System Card&quot;">​</a></h1><p><strong>Source</strong>: <a href="https://cdn.openai.com/o3-mini-system-card-feb10.pdf" target="_blank" rel="noreferrer">https://cdn.openai.com/o3-mini-system-card-feb10.pdf</a><strong>Published</strong>: January 31, 2025 <strong>PDF</strong>: <code>research/papers/pdfs/openai-o3-mini-system-card.pdf</code> (37 pp, full text archived)</p><hr><h2 id="摘要-依官方-pdf-第-1–3-頁-overview-整理" tabindex="-1">摘要（依官方 PDF 第 1–3 頁 overview 整理） <a class="header-anchor" href="#摘要-依官方-pdf-第-1–3-頁-overview-整理" aria-label="Permalink to &quot;摘要（依官方 PDF 第 1–3 頁 overview 整理）&quot;">​</a></h2><blockquote><p>The OpenAI o model series is trained with large-scale reinforcement learning to reason using chain of thought. These advanced reasoning capabilities provide new avenues for improving the safety and robustness of our models. In particular, our models can reason about our safety policies in context when responding to potentially unsafe prompts, through deliberative alignment. （引自 system card §1 Introduction）</p></blockquote><ul><li>o3-mini 屬 OpenAI o-series 推理模型：以大規模 RL 訓練「先思考再回答」（long chain of thought）。</li><li>透過 deliberative alignment（回答前顯式對安全規範推理），在 illicit advice、stereotyped response、已知 jailbreak 等風險 benchmark 上達到 SOTA parity。</li><li>本報告涵蓋 safety evaluations、external red teaming、Preparedness Framework evaluations。</li></ul><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="模型與定位" tabindex="-1">模型與定位 <a class="header-anchor" href="#模型與定位" aria-label="Permalink to &quot;模型與定位&quot;">​</a></h3><ul><li>推理導向（reasoning）模型，o-series 家族；強化 coding 與 research engineering 表現。</li><li>安全方法核心：deliberative alignment——模型在產出答案前顯式 reason through safety specifications。</li></ul><h3 id="關鍵能力-安全評估數字" tabindex="-1">關鍵能力 / 安全評估數字 <a class="header-anchor" href="#關鍵能力-安全評估數字" aria-label="Permalink to &quot;關鍵能力 / 安全評估數字&quot;">​</a></h3><ul><li>Preparedness Framework 整體評級（Safety Advisory Group, SAG）：<strong>Pre-Mitigation 模型整體 Medium risk</strong>。</li><li>各類別：<strong>Persuasion = Medium、CBRN（化生放核）= Medium、Model Autonomy = Medium、Cybersecurity = Low</strong>。</li><li>部署規則：post-mitigation score 為 Medium 或以下方可部署；High 或以下方可繼續開發。</li><li>里程碑：因 coding/research engineering 提升，o3-mini 為<strong>首個在 Model Autonomy 達 Medium 的模型</strong>；但在真實 ML 研究（自我改進相關）評測仍表現不佳，未達 High。</li></ul><h3 id="workspace-關聯-評估" tabindex="-1">Workspace 關聯（評估） <a class="header-anchor" href="#workspace-關聯-評估" aria-label="Permalink to &quot;Workspace 關聯（評估）&quot;">​</a></h3><ul><li>deliberative alignment「回答前顯式對規範推理」與 core.md IDENTIFY「實作前先講假設/成功條件」、APPLY「破壞性 gate」同構——皆是「行動前過閘」。</li><li>Preparedness 分級 → model-selection-grid 與 <code>core.md §PROPOSE 委派</code>（原 subagent-strategy.md） 能力下限的安全側依據；高自主/高風險任務應綁更強模型 + 人工確認，呼應「不可逆例外」。 〔v5.1：所引 workspace 細則已退役 → 見 <code>INDEX.md</code> §v5.1 規則退役對照〕</li><li>⚠️ 依官方公開資訊整理；數字以 PDF 全文為準（本檔僅摘 §1 與 Preparedness 結論）。</li></ul>',14)])])}const u=a(t,[["render",n]]);export{h as __pageData,u as default};
